      o.deposit = o.deposit != null ? o.deposit : V.depositFor(o.lines);
      Object.assign(o, { fines: o.fines || [], returns: o.returns || [], timeline: o.timeline || [], discount: o.discount || 0, advance: o.advance || 0, reminder: o.reminder || null, created: o.created || o.pickup });
